'use strict';
const $ = id => document.getElementById(id);
const state = { family:'reach', scenario:'baseline', group:0, stage:3 };
const groupNames=['All families','Disadvantaged (SEP)','Other eligible families'];
const stageNames=['No intervention','Families choose','Limited seats','Schools respond'];
const format=n=>n.toFixed(3), signed=n=>(n>=0?'+':'−')+Math.abs(n).toFixed(3);
const validFamilies={reach:['takeup50','takeup75','baseline'],target:['baseline','sepOnly','nonSepOnly'],cost:['baseline','cost10'],public:['baseline','publicResponds']};
function scenario(){return POLICY_DATA[state.scenario]}
function effect(s=scenario(),g=state.group,stage=state.stage){return s.effects?s.effects[g][stage]:s.values[g][stage]-s.values[g][0]}
function drawLever(){
 const target=$('lever-options');
 if(state.family==='reach'){
  const index=validFamilies.reach.indexOf(state.scenario);
  target.innerHTML=`<div class="lever-block"><div class="slider-value"><label for="takeup">Eligible families reached</label><strong id="takeup-output">${[50,75,100][index]}%</strong></div><input type="range" id="takeup" min="0" max="2" step="1" value="${index}" aria-valuetext="${[50,75,100][index]} percent take-up"><div class="range-ticks"><span>50%</span><span>75%</span><span>100%</span></div><p class="help">Move between the three take-up rates simulated in the paper. Higher-education households are not directly treated.</p></div>`;
  $('takeup').addEventListener('input',e=>{const i=Number(e.target.value);state.scenario=validFamilies.reach[i];$('takeup-output').textContent=[50,75,100][i]+'%';e.target.setAttribute('aria-valuetext',[50,75,100][i]+' percent take-up');render()});
 }else{
  const labels={target:['All eligible families','Disadvantaged (SEP) only','Other eligible families only'],cost:['Baseline costs','Marginal costs +10%'],public:['Private schools respond','Public schools respond too']};
  const note={target:'Full take-up within the selected group. All other assumptions stay at baseline.',cost:'Raise private schools’ unit cost of quality by 10%, keeping fixed per-student costs unchanged. Demand and capacity bars remain baseline-cost reference points.',public:'A sensitivity exercise that mechanically extends the private-school response rule to public schools.'};
  target.innerHTML=`<div class="option-set" role="group" aria-label="${$('policy-family').selectedOptions[0].textContent}">${validFamilies[state.family].map((key,i)=>`<button type="button" data-scenario="${key}" aria-pressed="${state.scenario===key}">${labels[state.family][i]}</button>`).join('')}</div><p class="help">${note[state.family]}</p>`;
  target.querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>{state.scenario=button.dataset.scenario;drawLever();render()}));
 }
}
function chart(){
 if(window.innerWidth<600){
 const values=scenario().values[state.group];let svg='<svg viewBox="0 0 330 238" role="presentation" aria-hidden="true">';
 values.forEach((v,i)=>{const y=19+i*57;svg+=`<text x="0" y="${y}" font-size="14" font-family="Arial,sans-serif" fill="#526179">${stageNames[i]}</text><rect x="0" y="${y+9}" width="${v/.85*276}" height="20" rx="3" fill="${i===0?'#a8b5cd':i===state.stage?'#2448e3':'#a5b6fc'}"/><text x="325" y="${y+25}" text-anchor="end" font-size="14" font-family="Arial,sans-serif" font-weight="600" fill="#2448e3">${format(v)}</text>`});$('chart').innerHTML=svg+'</svg>';$('chart').setAttribute('aria-label',stageNames.map((n,i)=>`${n}: ${format(values[i])} SD`).join('; '));return;
 }
 const values=scenario().values[state.group], w=670,h=232,top=27,bottom=177,xs=[104,258,412,566],max=.85;
 let svg=`<svg viewBox="0 0 ${w} ${h}" role="presentation" aria-hidden="true">`;
 for(const tick of [0,.2,.4,.6,.8]){const y=bottom-tick/max*(bottom-top);svg+=`<line x1="48" x2="645" y1="${y}" y2="${y}" stroke="#e5eaf2"/><text x="35" y="${y+4}" text-anchor="end" font-family="Arial,sans-serif" font-size="12" fill="#63718a">${tick.toFixed(1)}</text>`}
 values.forEach((v,i)=>{const y=bottom-v/max*(bottom-top),selected=i===state.stage,color=i===0?'#a8b5cd':(selected?'#2448e3':'#a5b6fc');svg+=`<rect class="bar-rect" x="${xs[i]-34}" y="${y}" width="68" height="${bottom-y}" rx="4" fill="${color}" opacity="${i>state.stage?.45:1}"/><text x="${xs[i]}" y="${y-9}" text-anchor="middle" font-size="15" font-family="Arial,sans-serif" font-weight="600" fill="${selected?'#2448e3':'#3f506c'}">${format(v)}</text><text x="${xs[i]}" y="202" text-anchor="middle" font-size="13" font-family="Arial,sans-serif" fill="#526179">${stageNames[i]}</text>${selected?`<circle cx="${xs[i]}" cy="219" r="3" fill="#2448e3"/>`:''}`});
 $('chart').innerHTML=svg+'</svg>';$('chart').setAttribute('aria-label',stageNames.map((n,i)=>`${n}: ${format(values[i])} SD`).join('; ')+`. Selected: ${stageNames[state.stage]}.`)
}
function render(){
 const s=scenario(),v=s.values[state.group],e=effect();
 $('scenario-tag').textContent=s.tag+' · '+groupNames[state.group];$('scenario-heading').textContent=s.title;
 $('effect').innerHTML=signed(e)+'<span> SD</span>';$('mobile-effect').textContent=signed(e)+' SD';$('quality').textContent=format(v[state.stage]);$('baseline').textContent=format(v[0])+' without the intervention';
 $('effect-note').textContent=s.effects?'Reported treatment effect':'Difference in rounded quality levels';
 $('stage-help').textContent=({1:'School prices and quality stay fixed; families can choose freely.',2:'Seat limits can bind at popular schools. A deferred-acceptance assignment allocates places; school prices and quality stay fixed.',3:'Seat limits remain, and private schools adjust quality. Public-school behavior follows the selected scenario.'})[state.stage];
 const titles={1:'Information changes families’ choices.',2:'Better-informed demand meets limited seats.',3:'Schools’ response changes the story.'};
 let description=state.stage===1?'The model shifts families’ demand using the experimental evidence. This stage abstracts from seat constraints and keeps school prices and quality fixed.':state.stage===2?'When popular schools fill up, some families are assigned elsewhere. Compare this stage with free choice to see how congestion changes the gain.':'Private schools adjust quality in response to the change in demand. Tuition and capacities stay fixed. That response can offset congestion, but its size depends on the model’s cost and behavior assumptions.';
 if(state.scenario==='cost10'&&state.stage===3) description='Increasing private schools’ unit cost of quality by 10% reduces the projected gain. The policy’s success depends on schools being able to respond affordably, as well as on families receiving information.';
 if(state.scenario==='cost10'&&state.stage<3) description='This is an unchanged baseline-cost reference point. The +10% cost sensitivity applies only to the final school-response equilibrium; select “Allow schools to respond” to see it.';
 if(state.scenario==='publicResponds'&&state.stage===3) description='This sensitivity extends the private-school response rule to public schools. It illustrates the role of supply assumptions; it is not an estimated public-school policy effect.';
 if((state.scenario==='sepOnly'&&state.group===2)||(state.scenario==='nonSepOnly'&&state.group===1)) description=state.stage===1?'This group does not directly receive information, so its demand-only outcome is unchanged. Move to limited seats or school response to see spillovers.':'This group does not directly receive information. Changes in its outcome arise through shared seats and, in the final stage, schools’ response.';
 $('insight-title').textContent=titles[state.stage];$('insight-text').textContent=description;
 $('results-table').innerHTML=`<div class="table-wrap"><table><caption>${s.tag}: expected school quality (SD)</caption><thead><tr><th scope="col">Families</th>${stageNames.map(n=>`<th scope="col">${n}</th>`).join('')}</tr></thead><tbody>${s.values.map((row,g)=>`<tr><th scope="row">${groupNames[g]}</th>${row.map(n=>`<td>${format(n)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 const se=(['cost10','publicResponds'].includes(state.scenario)&&state.stage<3?POLICY_DATA.baseline:s).se?.[state.group]?.[state.stage];$('uncertainty').textContent=se?`Reported standard error for the selected treatment effect: ${format(se)} SD (delta method). This propagates treatment-parameter uncertainty conditional on baseline demand, supply, capacities, and the model; it is not total uncertainty.`:'The manuscript table does not report a standard error for this selected sensitivity scenario. Displayed differences are descriptive model comparisons.';
 chart();
 window.dispatchEvent(new CustomEvent('policy:change',{detail:policySnapshot()}));
}
function policySnapshot(){return {...state,scenarioLabel:scenario().tag,groupLabel:groupNames[state.group],stageLabel:stageNames[state.stage],baseline:scenario().values[state.group][0],mean:scenario().values[state.group][state.stage],effect:effect(),sourceVersion:POLICY_DATA.sourceVersion};}
function navigate(){const page=['experiment','places','model','policy','researchers'].includes(location.hash.slice(1))?location.hash.slice(1):'policy';document.querySelectorAll('.page').forEach(s=>s.hidden=s.id!=='page-'+page);document.querySelectorAll('[data-page]').forEach(a=>{const selected=a.dataset.page===page;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(page==='researchers')window.scrollTo({top:0,left:0,behavior:'instant'});}
function configure(input){if(!input||typeof input!=='object')throw new Error('Expected a policy configuration.');const keys=Object.keys(input);if(keys.some(k=>!['family','scenario','group','stage'].includes(k)))throw new Error('Unknown setting.');const next={...state,...input};if(!validFamilies[next.family]?.includes(next.scenario)||![0,1,2].includes(next.group)||![1,2,3].includes(next.stage))throw new Error('Choose a supported policy scenario, group, and model stage.');Object.assign(state,next);$('policy-family').value=state.family;$('group').value=state.group;$('stage').value=state.stage;drawLever();render();return {...state,expectedQuality:scenario().values[state.group][state.stage],effect:effect(),units:'SD of normalized school value added',source:POLICY_DATA.sourceVersion}}
window.PolicyLab=Object.freeze({getState:policySnapshot,configure});
$('policy-family').addEventListener('change',e=>{state.family=e.target.value;state.scenario='baseline';drawLever();render()});$('group').addEventListener('change',e=>{state.group=Number(e.target.value);render()});$('stage').addEventListener('change',e=>{state.stage=Number(e.target.value);render()});$('reset').addEventListener('click',()=>configure({family:'reach',scenario:'baseline',group:0,stage:3}));$('jump-results').addEventListener('click',()=>document.querySelector('.results').scrollIntoView({behavior:'instant',block:'start'}));window.addEventListener('resize',chart);window.addEventListener('hashchange',navigate);drawLever();render();navigate();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_policy_scenario',title:'Configure policy scenario',description:'Select a paper-reported scenario and update the visible policy lab. Does not run a new equilibrium solver.',inputSchema:{type:'object',properties:{family:{type:'string',enum:Object.keys(validFamilies)},scenario:{type:'string',enum:Object.keys(POLICY_DATA).filter(k=>k!=='sourceVersion')},group:{type:'integer',enum:[0,1,2]},stage:{type:'integer',enum:[1,2,3]}},required:['family','scenario','group','stage'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{const result=configure(input);location.hash='policy';navigate();return result}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
